<?php require_login();$id=(int)($_GET['id']??0);$r=db()->query("SELECT * FROM routines WHERE id=$id AND user_id=".user_id())->fetch_assoc();if(!$r){echo '<div class="empty">Routine not found.</div>';return;}$prods=db()->query("SELECT p.* FROM products p JOIN routine_products rp ON rp.product_id=p.id WHERE rp.routine_id=$id ORDER BY rp.step_no");$today=db()->query("SELECT id FROM routine_logs WHERE user_id=".user_id()." AND routine_id=$id AND log_date='".date('Y-m-d')."'")->num_rows;?>
<section class="page-title"><span class="eyebrow"><?=e($r['time_of_day'])?></span><h1><?=e($r['name'])?></h1><p><?=e($r['description'])?> · <?=e($r['days'])?></p></section>
<div class="panel"><div class="section-head"><h2>Today</h2><form method="post" action="actions.php"><input type="hidden" name="action" value="log"><input type="hidden" name="routine_id" value="<?=$id?>"><button class="btn <?=$today?'soft':'primary'?>"><?=$today?'✓ Logged today':'Log today'?></button></form></div>
<div class="routine-steps"><?php $n=1;while($p=$prods->fetch_assoc()):?><div class="step"><b><?=$n++?></b><img src="<?=e($p['image'])?>"><div><small><?=e($p['brand'])?></small><h3><?=e($p['name'])?></h3><p><?=e($p['category'])?></p></div></div><?php endwhile;?></div>
<?php if($n===1):?><div class="empty">Belum ada produk. Tambahkan di bawah.</div><?php endif;?></div>
<div class="panel"><h2>Add a product</h2><form method="post" action="actions.php" class="add-row"><input type="hidden" name="action" value="add_routine_product"><input type="hidden" name="routine_id" value="<?=$id?>"><select name="product_id"><?php $x=db()->query("SELECT id,brand,name FROM products ORDER BY brand,name");while($p=$x->fetch_assoc()):?><option value="<?=$p['id']?>"><?=e($p['brand'].' — '.$p['name'])?></option><?php endwhile;?></select><button class="btn primary">Add</button></form></div>
<div class="panel"><h2>Compatibility check</h2><p class="notice">Demo warning engine: if this routine contains both strong exfoliating acids and retinol, Mafe flags it for review. Individual skin reactions vary.</p>
<?php $hasA=$hasR=false;$check=db()->query("SELECT p.ingredients_text FROM products p JOIN routine_products rp ON rp.product_id=p.id WHERE rp.routine_id=$id");while($z=$check->fetch_assoc()){if(stripos($z['ingredients_text'],'Salicylic')!==false)$hasA=true;if(stripos($z['ingredients_text'],'Retinol')!==false)$hasR=true;}if($hasA&&$hasR):?><div class="warning">⚠ Potential conflict: this routine combines a BHA/exfoliant product with retinol. Consider separating them and checking product directions.</div><?php else:?><div class="success">✓ No demo conflict detected.</div><?php endif;?></div>